        method: 'POST', url: `${supabaseUrl}/rest/v1/contacts`, headers: { ...headers, Prefer: 'return=representation' },
        body: { tenant_id: tenantId, name: incomingName, phone: phone || null, external_handle: handle, source_channel: 'whatsapp', metadata: initialMetadata },
      });
      contact = Array.isArray(created) ? created[0] || null : created || null;
      // A concurrent first message may have won a database constraint race. Reuse
      // the deterministic oldest contact if it already exists; never create again.
      if (!contact) {
        rows = await request.call(this, { method: 'GET', url: `${supabaseUrl}/rest/v1/contacts?select=id,name,phone,external_handle,source_channel,avatar_url,avatar_fetched_at,metadata${filter}`, headers });
        contact = Array.isArray(rows) ? rows[0] || null : null;
      }
      if (!contact) throw new Error('contact_create_unavailable');
    } else if (!isOwnerSaved) {
      const excludedSource = await checkOwnerSavedFromDb.call(this, tenantId, phone || contact.phone || handle);
      if (excludedSource) {
        isOwnerSaved = true;
        ownerSavedSource = excludedSource;
        const updatedMetadata = {
          ...metadata,
          whatsapp_owner_saved: true,
          whatsapp_owner_saved_source: ownerSavedSource,
          whatsapp_owner_saved_at: now,
        };
        await request.call(this, {
          method: 'PATCH', url: `${supabaseUrl}/rest/v1/contacts?id=eq.${encodeURIComponent(contact.id)}&tenant_id=eq.${encodeURIComponent(tenantId)}`,
          headers, body: { metadata: updatedMetadata },
        }).catch(() => {});
        contact.metadata = updatedMetadata;
      }
    }

    sync.is_owner_saved = isOwnerSaved;
    sync.owner_saved_source = ownerSavedSource;

    const currentName = String(contact.name || '').trim();
    const chosenName = usefulName(currentName, contact.phone || phone) ? currentName : incomingName;
    const identityPatch = {
      phone: phone || contact.phone || null,
      external_handle: handle,
      source_channel: 'whatsapp',
      ...(chosenName && chosenName !== currentName ? { name: chosenName } : {}),
    };
    if (Object.values(identityPatch).some((value) => value !== undefined)) {
      await request.call(this, {
        method: 'PATCH', url: `${supabaseUrl}/rest/v1/contacts?id=eq.${encodeURIComponent(contact.id)}&tenant_id=eq.${encodeURIComponent(tenantId)}`,
        headers, body: identityPatch,
      }).catch(() => {});
      contact = { ...contact, ...identityPatch };
    }

    const webhookAvatar = profilePictureFromPayload(input.raw_payload);
    const cachedAvatar = profilePictureFromPayload({ profilePictureUrl: contact.avatar_url });
    if (webhookAvatar) {
      await request.call(this, {
        method: 'PATCH', url: `${supabaseUrl}/rest/v1/contacts?id=eq.${encodeURIComponent(contact.id)}&tenant_id=eq.${encodeURIComponent(tenantId)}`,
        headers, body: { avatar_url: webhookAvatar, avatar_fetched_at: now },
      }).catch(() => {});
      sync = { status: hasDuplicates ? 'updated_historical_duplicate' : 'updated', avatarUrl: webhookAvatar, source: 'webhook', contactId: contact.id, tenantId };
      return;
    }
    if (cachedAvatar && avatarFresh(contact.avatar_fetched_at, photoTtlMs)) {
      sync = { status: hasDuplicates ? 'updated_historical_duplicate' : 'updated', avatarUrl: cachedAvatar, source: 'cache', contactId: contact.id, tenantId };
      return;
    }
    metadata = objectValue(contact.metadata);
    if (!cachedAvatar && avatarFresh(metadata.whatsapp_avatar_negative_fetched_at, noPhotoTtlMs)) {
      sync = { status: hasDuplicates ? 'updated_historical_duplicate' : 'updated', avatarUrl: null, source: 'negative_cache', contactId: contact.id, tenantId };
      return;
    }
    const suffix = tenantEnvSuffix(input.tenant_slug);
    const baseUrl = String(env(`EVOLUTION_API_URL_${suffix}`)).replace(/\/$/, '');
    const apiKey = env(`EVOLUTION_API_KEY_${suffix}`);
    const instance = String(input.instance || env(`EVOLUTION_INSTANCE_${suffix}`)).trim();
    if (!baseUrl || !apiKey || !instance) {
      sync = { status: 'updated', avatarUrl: cachedAvatar || null, source: 'provider_not_configured', contactId: contact.id, tenantId };
      return;
    }
    let response;
    try {
      response = await request.call(this, {
        method: 'POST', url: `${baseUrl}/chat/fetchProfilePictureUrl/${encodeURIComponent(instance)}`,
        headers: { apikey: apiKey, 'Content-Type': 'application/json' }, body: { number: handle },
      });
    } catch {
      // Transient provider failures deliberately do not touch avatar_fetched_at.
      sync = { status: 'updated', avatarUrl: cachedAvatar || null, source: 'evolution_error', contactId: contact.id, tenantId };
      return;
    }
    const avatarUrl = profilePictureFromPayload(response);
    if (avatarUrl) {
      await request.call(this, {
        method: 'PATCH', url: `${supabaseUrl}/rest/v1/contacts?id=eq.${encodeURIComponent(contact.id)}&tenant_id=eq.${encodeURIComponent(tenantId)}`,
        headers, body: { avatar_url: avatarUrl, avatar_fetched_at: now },
      }).catch(() => {});
      sync = { status: 'updated', avatarUrl, source: 'evolution', contactId: contact.id, tenantId };
      return;
    }
    if (noPhotoResponse(response)) {
      await request.call(this, {
        method: 'PATCH', url: `${supabaseUrl}/rest/v1/contacts?id=eq.${encodeURIComponent(contact.id)}&tenant_id=eq.${encodeURIComponent(tenantId)}`,
        headers, body: { avatar_url: null, avatar_fetched_at: now, metadata: { ...metadata, whatsapp_avatar_negative_fetched_at: now } },
      }).catch(() => {});
      sync = { status: 'updated', avatarUrl: null, source: 'negative_cache', contactId: contact.id, tenantId };
      return;
    }
    // A malformed/unknown provider payload is not proof of no photo.
    sync = { status: 'updated', avatarUrl: cachedAvatar || null, source: 'evolution_unconfirmed', contactId: contact.id, tenantId };
  } catch {
    // Contacts and profile pictures are enrichment only: message persistence and
    // customer response must proceed even when this integration is unavailable.
    sync = { status: 'error', avatarUrl: null, source: 'contact_sync_error' };
  }
}

await syncWhatsappContact.call(this);
sync.is_owner_saved = isOwnerSaved;
sync.owner_saved_source = ownerSavedSource;
return { json: {
  ...input,
  remoteJid: handle || input.remoteJid,
  phone: phone || input.phone,
  tenant_id: sync.tenantId || input.tenant_id,
  contact_id: sync.contactId || input.contact_id,
  is_owner_saved: Boolean(sync.is_owner_saved),
  owner_saved_source: sync.owner_saved_source || null,
  contact_sync: sync,
  avatarUrl: sync.avatarUrl || input.avatarUrl || null,
  raw_payload: {
    ...objectValue(input.raw_payload),
    contact_sync: sync,
    is_owner_saved: Boolean(sync.is_owner_saved),
    owner_saved_source: sync.owner_saved_source || null,
  },
} };

// Ingestion infrastructure only. This node materializes an n8n-native binary
// item; a dedicated HTTP Request node owns the Storage upload.
function unwrapWhatsAppMessage(raw = {}) {
  let message = raw?.data?.message || raw?.message || raw || {};
  for (const key of ['ephemeralMessage', 'viewOnceMessage', 'viewOnceMessageV2', 'documentWithCaptionMessage']) {
    if (message?.[key]?.message) message = message[key].message;
  }
  return message;
}

function mediaNumber(value) {
  if (Number.isFinite(Number(value))) return Math.max(0, Number(value));
  if (value && typeof value === 'object' && Number.isFinite(Number(value.low))) {
    return (Number(value.low) >>> 0) + (Number(value.high || 0) >>> 0) * 4294967296;
  }
  return 0;
}

function mediaError(error, fallback) {
  return String(error?.message || error || fallback)
    .replace(/https?:\/\/\S+/gi, '[url]')
    .replace(/[\r\n]+/g, ' ')
    .slice(0, 180);
}

function extensionFor(kind, mimeType, fileName = '') {
  const fromName = String(fileName).match(/\.([a-z0-9]{1,12})$/i)?.[1];
  if (fromName) return fromName.toLowerCase();
  const byMime = {
    'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp',
    'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/webm': 'webm',
    'video/mp4': 'mp4', 'video/webm': 'webm', 'video/3gpp': '3gp',
    'application/pdf': 'pdf',
  };
  return byMime[mimeType] || (kind === 'sticker' ? 'webp' : kind === 'document' ? 'bin' : kind);
}

function allowedMime(kind, mimeType) {
  const allowed = {
    image: ['image/jpeg', 'image/png', 'image/webp'],
    sticker: ['image/webp'],
    audio: ['audio/ogg', 'audio/mpeg', 'audio/mp3', 'audio/mp4', 'audio/m4a', 'audio/wav', 'audio/x-wav', 'audio/aac', 'audio/flac', 'audio/webm'],
    video: ['video/mp4', 'video/webm', 'video/3gpp'],
  };
  return kind === 'document'
    ? /^[a-z0-9.+-]+\/[a-z0-9.+-]+$/i.test(mimeType)
    : Boolean(allowed[kind]?.includes(mimeType));
}

function magicFor(mimeType, bytes) {
  if (!bytes || bytes.length < 4) throw new Error('media_payload_empty');
  const magic = Buffer.from(bytes.subarray(0, Math.min(bytes.length, 12))).toString('hex');
  const has = (...expected) => expected.every((byte, index) => bytes[index] === byte);
  const mime = String(mimeType || '').toLowerCase();
  if ((mime === 'image/jpeg' || mime === 'image/jpg') && !has(0xff, 0xd8, 0xff)) throw new Error('media_magic_mismatch');
  if (mime === 'image/png' && !has(0x89, 0x50, 0x4e, 0x47)) throw new Error('media_magic_mismatch');
  if (mime === 'image/webp' && (bytes.length < 12 || bytes.toString('ascii', 0, 4) !== 'RIFF' || bytes.toString('ascii', 8, 12) !== 'WEBP')) throw new Error('media_magic_mismatch');
  if (mime === 'audio/ogg' && !has(0x4f, 0x67, 0x67, 0x53)) throw new Error('media_magic_mismatch');
  if (mime === 'application/pdf' && !has(0x25, 0x50, 0x44, 0x46)) throw new Error('media_magic_mismatch');
  if (['video/mp4', 'audio/mp4', 'audio/m4a'].includes(mime) && !bytes.subarray(0, Math.min(bytes.length, 32)).toString('ascii').includes('ftyp')) throw new Error('media_magic_mismatch');
  return magic;
}

function sourceDescriptor(input) {
  const message = unwrapWhatsAppMessage(input.raw_payload);
  const source = input?.queued?.event_id ? input : input;
  const fallback = input?.source_media || {};
  const entries = [
    ['image', message.imageMessage], ['audio', message.audioMessage], ['video', message.videoMessage],
    ['document', message.documentMessage], ['sticker', message.stickerMessage],
  ];
  const found = entries.find(([, value]) => value && typeof value === 'object');
  const kind = found?.[0] || String(fallback.kind || '').toLowerCase();
  if (!kind) return null;
  const raw = found?.[1] || {};
  const defaults = { image: 'image/jpeg', audio: 'audio/ogg', video: 'video/mp4', document: 'application/octet-stream', sticker: 'image/webp' };
  const mimeType = String(fallback.mime_type || raw.mimetype || raw.mimeType || defaults[kind] || '').split(';')[0].trim().toLowerCase();
  return {
    kind,
    category: kind,
    source: 'whatsapp',
    caption: String(fallback.caption || raw.caption || ''),
    fileName: String(fallback.file_name || raw.fileName || raw.file_name || ''),
    mimeType,
    size: mediaNumber(fallback.file_length || raw.fileLength || raw.file_length),
    duration: mediaNumber(fallback.duration || raw.seconds || raw.duration),
    width: mediaNumber(fallback.width || raw.width),
    height: mediaNumber(fallback.height || raw.height),
  };
}

const input = $json;
const queued = input.queued || {};
const descriptor = sourceDescriptor(input);
const eventId = String(queued.event_id || '').trim();
const messageId = String(input.messageId || '').trim();
const limit = 10 * 1024 * 1024;

if (!descriptor || !eventId || queued.duplicate) {
  return { json: { ...input, media_ingestion: { present: Boolean(descriptor), should_upload: false, skipped: queued.duplicate ? 'duplicate' : 'not_media' } } };
}

const bucket = String($env.WHATSAPP_MEDIA_BUCKET || 'channel-media').trim();
const safeChat = String(input.remoteJid || '').replace(/[^a-zA-Z0-9._-]/g, '_');
const safeMessageId = messageId.replace(/[^a-zA-Z0-9._-]/g, '_');
const base = {
  ...descriptor,
  bucket,
  storagePath: [String(input.tenant_slug || '').replace(/[^a-zA-Z0-9_-]/g, ''), 'whatsapp', safeChat, `${safeMessageId}.${extensionFor(descriptor.kind, descriptor.mimeType, descriptor.fileName)}`].join('/'),
  encoding: 'binary',
  verified: false,
};

function failed(status, error) {
  return { json: { ...input, media_ingestion: { present: true, should_upload: false, event_id: eventId, external_message_id: messageId, media: { ...base, status, error: mediaError(error, status) } } } };
}

if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,62}$/.test(bucket)) return failed('storage_error', 'media_storage_bucket_invalid');
if (!allowedMime(descriptor.kind, descriptor.mimeType)) return failed('unsupported', 'media_format_unsupported');
if (descriptor.size > limit) return failed('skipped_too_large', 'media_too_large');

let downloaded;
try {
  const suffix = String(input.tenant_slug || '').toUpperCase().replace(/[^A-Z0-9]/g, '_');
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: String($env[`EVOLUTION_API_URL_${suffix}`] || '').replace(/\/$/, '') + '/chat/getBase64FromMediaMessage/' + encodeURIComponent(String(input.instance || $env[`EVOLUTION_INSTANCE_${suffix}`] || '')),
    headers: { apikey: $env[`EVOLUTION_API_KEY_${suffix}`], 'Content-Type': 'application/json' },
    body: { message: { key: { id: messageId, remoteJid: input.remoteJid, fromMe: false } }, convertToMp4: false },
    json: true,
    timeout: 30000,
  });
  downloaded = response || {};
} catch (error) {
  return failed('unavailable', 'media_download_failed');
}

try {
  const mimeType = String(downloaded.mimetype || downloaded.mimeType || descriptor.mimeType).split(';')[0].trim().toLowerCase();
  const base64 = String(downloaded.base64 || '').replace(/^data:[^,]+;base64,/, '');
  if (!allowedMime(descriptor.kind, mimeType)) throw new Error('media_format_unsupported');
  if (!base64 || base64.length % 4 !== 0 || !/^[A-Za-z0-9+/]+={0,2}$/.test(base64)) throw new Error('media_invalid_base64');
  const bytes = Buffer.from(base64, 'base64');
  if (!bytes.length) throw new Error('media_payload_empty');
  if (bytes.length > limit) throw new Error('media_too_large');
  const magic = magicFor(mimeType, bytes);
  const media = { ...base, mimeType, size: bytes.length, storagePath: base.storagePath.replace(/\.[^.]+$/, `.${extensionFor(descriptor.kind, mimeType, descriptor.fileName)}`), status: 'pending', magic };
  const binary = await this.helpers.prepareBinaryData(bytes, media.fileName || `whatsapp-${messageId}.${extensionFor(descriptor.kind, mimeType, descriptor.fileName)}`, mimeType);
  return {
    json: { ...input, media_ingestion: { present: true, should_upload: true, event_id: eventId, external_message_id: messageId, expectedSize: bytes.length, mimeType, magic, media } },
    binary: { media_file: binary },
  };
} catch (error) {
  const code = String(error?.message || '');
  return failed(code === 'media_too_large' ? 'skipped_too_large' : code === 'media_magic_mismatch' || code === 'media_format_unsupported' ? 'unsupported' : 'storage_error', code || 'media_prepare_failed');
}

// Runs after the native HTTP Request node. Storage is considered available only
// after a 2xx upload and a scoped HEAD whose exact length matches the bytes sent.
function compactMediaError(error, fallback) {
  return String(error?.message || error || fallback)
    .replace(/https?:\/\/\S+/gi, '[url]')
    .replace(/[\r\n]+/g, ' ')
    .slice(0, 180);
}

function responseStatus(value) {
  return Number(value?.statusCode || value?.status || value?.body?.statusCode || 0);
}

function headerValue(headers, name) {
  const lower = String(name).toLowerCase();
  const entries = Object.entries(headers || {});
  return entries.find(([key]) => String(key).toLowerCase() === lower)?.[1] || '';
}

function preparedInput() {
  if ($json?.media_ingestion) return { json: $json, binary: $binary || {} };
  const item = $('Preparar Mídia WhatsApp').item;
  return { json: item?.json || {}, binary: item?.binary || {} };
}

const prepared = preparedInput();
const source = prepared.json;
const job = source.media_ingestion || {};

if (!job.present) return { json: source, binary: prepared.binary };

let media = { ...(job.media || {}) };
if (job.should_upload) {
  const status = responseStatus($json);
  if (status < 200 || status >= 300) {
    media = { ...media, status: 'storage_error', verified: false, error: `storage_upload_failed:${status || 'unknown'}` };
  } else {
    try {
      const base = String($env.SUPABASE_URL || '').replace(/\/$/, '');
      const serviceKey = $env.SUPABASE_SERVICE_ROLE_KEY;
      const verify = await this.helpers.httpRequest({
        method: 'HEAD',
        url: `${base}/storage/v1/object/${encodeURIComponent(media.bucket)}/${media.storagePath}`,
        headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}` },
        json: false,
        returnFullResponse: true,
        timeout: 20000,
      });
      const verifyStatus = responseStatus(verify);
      if (verifyStatus < 200 || verifyStatus >= 300) throw new Error(`storage_verify_failed:${verifyStatus || 'unknown'}`);
      const storedSize = Number(headerValue(verify.headers || verify.response?.headers, 'content-length'));
      if (!Number.isFinite(storedSize) || storedSize !== Number(job.expectedSize)) throw new Error('storage_size_mismatch');
      media = { ...media, status: 'stored', verified: true, storedSize, size: storedSize, magic: job.magic || media.magic || '' };
    } catch (error) {
      const code = String(error?.message || 'storage_verify_failed');
      media = { ...media, status: 'storage_error', verified: false, error: code.includes('storage_size_mismatch') ? 'storage_size_mismatch' : compactMediaError(error, 'storage_verify_failed') };
    }
  }
}

const tenantId = String(source.tenant_id || '').trim();
const eventId = String(job.event_id || '').trim();
const externalMessageId = String(job.external_message_id || '').trim();
const chatId = String(source.remoteJid || '').trim();
let persistenceError = '';

if (tenantId && eventId && externalMessageId && chatId) {
  const base = String($env.SUPABASE_URL || '').replace(/\/$/, '');
  const serviceKey = $env.SUPABASE_SERVICE_ROLE_KEY;
  const scope = `${base}/rest/v1/channel_events?tenant_id=eq.${encodeURIComponent(tenantId)}&channel_type=eq.whatsapp&external_conversation_id=eq.${encodeURIComponent(chatId)}&id=eq.${encodeURIComponent(eventId)}&external_message_id=eq.${encodeURIComponent(externalMessageId)}`;
  try {
    const rows = await this.helpers.httpRequest({ method: 'GET', url: `${scope}&select=id,raw_payload&limit=1`, headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}` }, json: true, timeout: 10000 });
    if (!Array.isArray(rows) || rows.length !== 1) throw new Error('media_event_scope_mismatch');
    const rawPayload = rows[0].raw_payload && typeof rows[0].raw_payload === 'object' ? rows[0].raw_payload : {};
    const saved = await this.helpers.httpRequest({
      method: 'PATCH', url: scope, headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}`, 'Content-Type': 'application/json', Prefer: 'return=representation' },
      body: { raw_payload: { ...rawPayload, media } }, json: true, timeout: 10000,
    });
    if (!Array.isArray(saved) || saved.length !== 1) throw new Error('media_event_not_persisted');
  } catch (error) {
    persistenceError = compactMediaError(error, 'media_persistence_failed');
    media = { ...media, status: 'persistence_error', verified: false, error: persistenceError };
  }
}

return {
  json: { ...source, media_ingestion: { ...job, media, persisted: !persistenceError, persistence_error: persistenceError || undefined } },
  binary: prepared.binary,
};
